:root {
  --bg: #f5f6f8;
  --panel: #ffffff;
  --border: #e2e5ea;
  --text: #1c2330;
  --muted: #6b7280;
  --primary: #2f6fed;
  --primary-dark: #2559c4;
  --danger: #c0392b;
  --shadow: 0 1px 3px rgba(20, 30, 50, 0.08);
  --radius: 10px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.app {
  max-width: 760px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.9rem;
}

.tagline {
  margin: 0.25rem 0 1.5rem;
  color: var(--muted);
}

.save-panel,
.controls,
.list-panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.25rem;
  margin-bottom: 1.25rem;
}

.save-form {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.field label {
  font-size: 0.85rem;
  font-weight: 600;
}

.hint {
  font-weight: 400;
  color: var(--muted);
}

input[type="text"],
input[type="search"],
select {
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
  background: #fff;
  color: var(--text);
}

input:focus,
select:focus {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.btn {
  cursor: pointer;
  border: none;
  border-radius: 8px;
  padding: 0.55rem 0.95rem;
  font-size: 0.9rem;
  font-weight: 600;
}

.btn.primary {
  background: var(--primary);
  color: #fff;
  align-self: flex-start;
}

.btn.primary:hover {
  background: var(--primary-dark);
}

.btn.subtle {
  background: #eef1f6;
  color: var(--text);
}

.btn.subtle:hover {
  background: #e2e6ee;
}

.btn.link {
  background: transparent;
  color: var(--primary);
  padding: 0.2rem 0.35rem;
}

.btn.link.danger {
  color: var(--danger);
}

.form-message {
  margin: 0;
  font-size: 0.88rem;
  padding: 0.5rem 0.7rem;
  border-radius: 8px;
}

.form-message.error {
  background: #fdecea;
  color: var(--danger);
}

.form-message.warning {
  background: #fef6e0;
  color: #8a6d1a;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.6rem;
}

.controls .search {
  flex: 1 1 220px;
}

.tag-filter-label {
  font-size: 0.85rem;
  font-weight: 600;
}

.bookmark-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.bookmark-item {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.85rem 1rem;
}

.bookmark-title {
  font-size: 1.05rem;
  font-weight: 600;
  text-decoration: none;
  color: var(--text);
  overflow-wrap: anywhere;
}

.bookmark-title:hover {
  color: var(--primary);
  text-decoration: underline;
}

.bookmark-url {
  display: block;
  color: var(--muted);
  font-size: 0.85rem;
  overflow-wrap: anywhere;
  max-height: 1.4em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookmark-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.5rem;
}

.tag-chip {
  background: #eef2fb;
  color: var(--primary-dark);
  border-radius: 999px;
  padding: 0.12rem 0.6rem;
  font-size: 0.78rem;
}

.bookmark-actions {
  margin-top: 0.55rem;
  display: flex;
  gap: 0.5rem;
}

.state-message {
  text-align: center;
  color: var(--muted);
  padding: 2rem 1rem;
}

.state-message h2 {
  margin: 0 0 0.4rem;
  font-size: 1.1rem;
  color: var(--text);
}

.edit-dialog {
  border: none;
  border-radius: var(--radius);
  padding: 1.5rem;
  max-width: 460px;
  width: 90%;
  box-shadow: 0 10px 40px rgba(20, 30, 50, 0.25);
}

.edit-dialog::backdrop {
  background: rgba(15, 22, 38, 0.45);
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.6rem;
  margin-top: 0.5rem;
}

