:root {
  --bg: #f5f6f8;
  --panel: #ffffff;
  --border: #e2e5ea;
  --text: #1c2330;
  --muted: #6b7280;
  --primary: #2f6fed;
  --primary-dark: #2559c4;
  --danger: #c0392b;
  --shadow: 0 1px 3px rgba(20, 30, 50, 0.08);
  --radius: 10px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.app {
  max-width: 760px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.9rem;
}

.tagline {
  margin: 0.25rem 0 1.5rem;
  color: var(--muted);
}

.save-panel,
.controls,
.list-panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.25rem;
  margin-bottom: 1.25rem;
}

.save-form {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.field label {
  font-size: 0.85rem;
  font-weight: 600;
}

.hint {
  font-weight: 400;
  color: var(--muted);
}

input[type="text"],
input[type="search"],
select {
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
  background: #fff;
  color: var(--text);
}

input:focus,
select:focus {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.btn {
  cursor: pointer;
  border: none;
  border-radius: 8px;
  padding: 0.55rem 0.95rem;
  font-size: 0.9rem;
  font-weight: 600;
}

.btn.primary {
  background: var(--primary);
  color: #fff;
  align-self: flex-start;
}

.btn.primary:hover {
  background: var(--primary-dark);
}

.btn.subtle {
  background: #eef1f6;
  color: var(--text);
}

.btn.subtle:hover {
  background: #e2e6ee;
}

.btn.link {
  background: transparent;
  color: var(--primary);
  padding: 0.2rem 0.35rem;
}

.btn.link.danger {
  color: var(--danger);
}

.form-message {
  margin: 0;
